'use strict';
// A terminal colour library with a chainable builder, written the way such libraries
// commonly are: every style is a getter on a shared prototype, the builder is a function
// object whose prototype is set to that prototype, and an instance is a plain object whose
// prototype is set to the library's.
const codes = {
  bold: [1, 22],
  dim: [2, 22],
  underline: [4, 24],
  cyan: [36, 39],
  magenta: [35, 39],
};

const styles = Object.create(null);
for (const [name, [open, close]] of Object.entries(codes)) {
  styles[name] = {
    get() {
      const builder = createBuilder(this, `\u001B[${open}m`, `\u001B[${close}m`);
      Object.defineProperty(this, name, { value: builder });
      return builder;
    },
  };
}

const proto = Object.defineProperties(() => {}, {
  ...styles,
  level: {
    enumerable: true,
    get() {
      return this._generator.level;
    },
    set(level) {
      this._generator.level = level;
    },
  },
});

function createBuilder(self, open, close) {
  const builder = (...parts) => applyStyle(builder, parts.join(' '));
  // The builder is a function, and it gets the style getters by having its prototype set.
  Object.setPrototypeOf(builder, proto);
  builder._generator = self._generator ?? self;
  builder._open = (self._open ?? '') + open;
  builder._close = close + (self._close ?? '');
  return builder;
}

function applyStyle(builder, text) {
  return builder.level > 0 ? builder._open + text + builder._close : text;
}

function tintFactory(options) {
  const tint = {};
  tint.level = options && options.level !== undefined ? options.level : 1;
  tint.template = (...parts) => parts.join(' ');
  Object.setPrototypeOf(tint, Tint.prototype);
  Object.setPrototypeOf(tint.template, tint);
  tint.template.Instance = TintClass;
  return tint.template;
}

class TintClass {
  constructor(options) {
    // eslint-disable-next-line no-constructor-return
    return tintFactory(options);
  }
}

function Tint(options) {
  return tintFactory(options);
}
Object.defineProperties(Tint.prototype, styles);

module.exports = Tint();
